templates.body:
{
  "format": "ankhimate-runtime",
  "format_version": 2,
  "context_version": {{context_version}},
  "name": {{json project.name}},
  "fps": {{project.fps}},
  "bones": [
{{#each skeleton.bones}}    {"name":{{json name}},"parent":{{parent_index}},"length":{{#if @root.skeleton.precise_bind_numbers}}{{json length}}{{else}}{{round length 4}}{{/if}},"x":{{#if @root.skeleton.precise_bind_numbers}}{{json x}}{{else}}{{round x 4}}{{/if}},"y":{{#if @root.skeleton.precise_bind_numbers}}{{json y}}{{else}}{{round y 4}}{{/if}},"rotation":{{#if @root.skeleton.precise_bind_numbers}}{{json rotation}}{{else}}{{round rotation 4}}{{/if}},"scaleX":{{#if @root.skeleton.precise_bind_numbers}}{{json scale_x}}{{else}}{{round scale_x 4}}{{/if}},"scaleY":{{#if @root.skeleton.precise_bind_numbers}}{{json scale_y}}{{else}}{{round scale_y 4}}{{/if}},"shearX":{{#if @root.skeleton.precise_bind_numbers}}{{json shear_x}}{{else}}{{round shear_x 4}}{{/if}},"shearY":{{#if @root.skeleton.precise_bind_numbers}}{{json shear_y}}{{else}}{{round shear_y 4}}{{/if}},"inheritRotation":{{inherit_rotation}},"inheritScale":{{inherit_scale}},"inheritReflect":{{inherit_reflect}}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "slots": [
{{#each skeleton.slots}}    {"name":{{json name}},"bone":{{json bone}},"attachment":{{#if attachment}}{{json attachment}}{{else}}null{{/if}},"color":"{{hex color}}"{{#if dark_color}},"dark_color":{{json dark_color}}{{/if}},"blend":{{json blend}}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "drawOrder": {{json skeleton.draw_order}},
  "defaultSkin": {{json skeleton.default_skin}},
  "skins": [
{{#each skeleton.skins}}    {"name":{{json name}},"bones":{{json bones}},"constraints":{{json constraints}},"attachments":[
{{#each entries}}      {"slot":{{json slot}},"name":{{json name}},"attachment":{{json attachment}}}{{#unless @last}},{{/unless}}
{{/each}}    ]}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "constraints": [
{{#each skeleton.constraints}}    {{json this}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "constraintOrder": {{json skeleton.constraint_order}},
  "animations": {
{{#each animations}}    {{json name}}: {
      "duration": {{round duration 4}},
      "looping": {{looping}},
      "bones": [
{{#each bones}}        {"name":{{json name}}{{#if translate_x}},"translate_x":{{json translate_x}}{{/if}}{{#if translate_y}},"translate_y":{{json translate_y}}{{/if}}{{#if rotate}},"rotate":{{json rotate}}{{/if}}{{#if scale_x}},"scale_x":{{json scale_x}}{{/if}}{{#if scale_y}},"scale_y":{{json scale_y}}{{/if}}{{#if shear_x}},"shear_x":{{json shear_x}}{{/if}}{{#if shear_y}},"shear_y":{{json shear_y}}{{/if}}}{{#unless @last}},{{/unless}}
{{/each}}      ],
      "slots": {{json slots}},
      "deform": {{json deform}},
      "drawOrder": {{json draw_order}},
      "ik": {{json ik}},
      "transform": {{json transform}},
      "events": {{json events}}
    }{{#unless @last}},{{/unless}}
{{/each}}  },
  "atlas": {{#if atlas}}{"pages":{{json atlas.pages}},"regions":{{json atlas.regions}}}{{else}}null{{/if}}
}
